mod public_round;
struct Input { blocks: Vec<Block>, seed: Block, size: usize }
thread_local! { static INPUT: RefCell<Input> = const { RefCell::new(Input { blocks: Vec::new(), seed: Block::ZERO, size: 0 }) }; }
fn next(state: &mut u32) -> u32 {
    *state ^= *state << 13;
    *state ^= *state >> 17;
    *state ^= *state << 5;
    *state
}
fn block(state: &mut u32) -> Block {
    let mut bytes = [0u8; 16];
    for word in bytes.chunks_mut(4) { word.copy_from_slice(&next(state).to_le_bytes()); }
    Block::new(bytes)
}
#[no_mangle]
pub extern "C" fn verify_rounds(seeds: u32, rounds: u32) {
    for seed in 0..seeds {
        let mut state = seed ^ 0x517cc1b7;
        for _ in 0..rounds {
            let mut inputs = [Block::ZERO; 8];
            let mut keys = [Block::ZERO; 8];
            for input in &mut inputs { *input = block(&mut state); }
            for key in &mut keys { *key = block(&mut state); }
            let mut expected = inputs;
            aes::hazmat::cipher_round_par(bytemuck::cast_mut(&mut expected), bytemuck::cast_ref(&keys));
            public_round::apply(&mut inputs, &keys);
            assert_eq!(bytemuck::cast_slice::<_, u8>(&inputs), bytemuck::cast_slice::<_, u8>(&expected));
        }
    }
}
#[no_mangle]
pub extern "C" fn verify_refills(seeds: u32, rounds: u32) {
    for seed in 0..seeds {
        let mut state = seed ^ 0x617cc1b7;
        let seed = block(&mut state);
        let mut actual = candidate_rng::FastAesRng::new(seed);
        let mut expected = reference_rng::FastAesRng::new(seed);
        assert_eq!(actual.bytes(), expected.bytes());
        for _ in 0..rounds {
            actual.refill();
            expected.refill();
            assert_eq!(actual.bytes(), expected.bytes());
        }
    }
}
#[no_mangle]
pub extern "C" fn prepare(size: u32, seed: u32) {
    assert!(size >= 32 && size <= 524288);
    let mut random = seed ^ 0x717cc1b7;
    let public_seed = if seed == 0 { cryprot_codes::ExConvCodeConfig::default().seed } else { block(&mut random) };
    let blocks = (0..size * 2).map(|_| block(&mut random)).collect();
    INPUT.with(|cell| *cell.borrow_mut() = Input { blocks, seed: public_seed, size: size as usize });
}
#[no_mangle]
pub extern "C" fn encode(mode: u32) {
    INPUT.with(|cell| {
        let mut input = cell.borrow_mut();
        if mode == 0 {
            let config = reference_codes::ExConvCodeConfig { seed: input.seed, ..Default::default() };
            reference_codes::ExConvCode::new_with_conf(input.size, config).dual_encode(&mut input.blocks);
        } else {
            let config = cryprot_codes::ExConvCodeConfig { seed: input.seed, ..Default::default() };
            cryprot_codes::ExConvCode::new_with_conf(input.size, config).dual_encode(&mut input.blocks);
        }
    });
}
#[no_mangle]
pub extern "C" fn output_ptr() -> *const u8 { INPUT.with(|cell| cell.borrow().blocks.as_ptr().cast()) }
#[no_mangle]
pub extern "C" fn output_len() -> usize { INPUT.with(|cell| cell.borrow().blocks.len() * 16) }
pub fn snapshot() -> Vec<u8> { INPUT.with(|cell| bytemuck::cast_slice::<_, u8>(&cell.borrow().blocks).to_vec()) }

