fn main() {
    let directory = std::path::PathBuf::from(std::env::args().nth(1).expect("output directory"));
    std::fs::create_dir_all(&directory).unwrap();
    encoder_screen::verify_rounds(32, 512);
    encoder_screen::verify_refills(32, 512);
    for size in [32, 1024, 524288] {
        for seed in [0, 1, 2, 3, 4] {
            encoder_screen::prepare(size, seed);
            encoder_screen::encode(0);
            let expected = encoder_screen::snapshot();
            encoder_screen::prepare(size, seed);
            encoder_screen::encode(1);
            assert_eq!(expected, encoder_screen::snapshot());
            std::fs::write(directory.join(format!("{size}-{seed}.bin")), expected).unwrap();
        }
    }
    println!("Complete AES-round, repeated-refill, and encoder buffers match.");
}

