import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { performance } from 'node:perf_hooks';

const root = '/private/tmp/ml-dsa-stages-ahtjjz95';
const wasm = await readFile(`${root}/encoder-screen/target/wasm32-unknown-unknown/release/encoder_screen.wasm`);
const { instance } = await WebAssembly.instantiate(wasm, {});
const api = instance.exports;
api.verify_rounds(32, 512);
api.verify_refills(32, 512);
const vectors = [];
for (const size of [32, 1024, 524288]) {
  for (const seed of [0, 1, 2, 3, 4]) {
    const expected = await readFile(`${root}/encoder-goldens/${size}-${seed}.bin`);
    for (const mode of [0, 1]) {
      api.prepare(size, seed);
      api.encode(mode);
      const output = currentOutput();
      assert.equal(output.equals(expected), true, `Encoder mismatch: ${size}/${seed}/${mode}`);
      vectors.push({ size, seed, mode, bytesCompared: output.length, sha256: digest(output) });
    }
  }
}
const samples = [];
for (let repetition = 0; repetition < 12; repetition++) {
  for (const mode of repetition % 2 === 0 ? [0, 1] : [1, 0]) {
    api.prepare(524288, repetition + 100);
    const start = performance.now();
    api.encode(mode);
    samples.push({ repetition, mode, elapsedMs: performance.now() - start, sha256: digest(currentOutput()) });
  }
}
for (let repetition = 0; repetition < 12; repetition++) {
  const pair = samples.slice(repetition * 2, repetition * 2 + 2);
  assert.equal(pair[0].sha256, pair[1].sha256);
}
const baseline = median(0);
const candidate = median(1);
const sourceFiles = ['src/lib.rs', 'src/main.rs', 'src/candidate_rng.rs', 'Cargo.toml', 'Cargo.lock', 'run.mjs'];
const sources = {};
for (const file of sourceFiles) sources[file] = await readFile(`${root}/encoder-screen/${file}`, 'utf8');
await writeFile('/private/tmp/ml-dsa-stage-encoder-screen.json', JSON.stringify({
  scope: 'Local Node Wasm SIMD with public deterministic inputs. No complete preparation claim. Unsupported RNG backend is confined to this probe. Mode0 is the pre-change encoder; mode1 is the candidate. Seed0 uses the production default matrix seed.',
  wasmSha256: digest(wasm),
  rounds: { seeds: 32, roundsPerSeed: 512, blocksPerRound: 8, fullBytesCompared: true },
  refills: { seeds: 32, roundsPerSeed: 512, bufferBytes: 4096, fullBytesCompared: true },
  vectors, samples, baselineMedianMs: baseline, candidateMedianMs: candidate, sources,
}, null, 2));
console.log({ baselineMedianMs: baseline, candidateMedianMs: candidate, reductionPercent: 100 * (baseline - candidate) / baseline });
function currentOutput() {
  return Buffer.from(api.memory.buffer, api.output_ptr(), api.output_len());
}
function digest(bytes) {
  return createHash('sha256').update(bytes).digest('hex');
}
function ascending(a, b) {
  return a - b;
}
function median(mode) {
  const times = [];
  for (const sample of samples) if (sample.mode === mode) times.push(sample.elapsedMs);
  times.sort(ascending);
  return (times[5] + times[6]) / 2;
}
